<script setup lang="ts">import relations from '../../data/relations.json';const nodes=[...new Set(relations.relations.flatMap((r:any)=>[r.subject,r.object]))];const x=(i:number)=>80+(i%3)*260;const y=(i:number)=>70+Math.floor(i/3)*110</script><template><svg class="lore-svg" viewBox="0 0 900 350" role="img" aria-label="Relations graph"><g v-for="(r,i) in relations.relations" :key="i"><line :x1="x(nodes.indexOf(r.subject))+80" :y1="y(nodes.indexOf(r.subject))+20" :x2="x(nodes.indexOf(r.object))+80" :y2="y(nodes.indexOf(r.object))+20" stroke="currentColor" opacity=".35"/><text :x="(x(nodes.indexOf(r.subject))+x(nodes.indexOf(r.object)))/2+80" :y="(y(nodes.indexOf(r.subject))+y(nodes.indexOf(r.object)))/2" font-size="11">{{r.predicate}}</text></g><g v-for="(n,i) in nodes" :key="n"><rect :x="x(i)" :y="y(i)" width="160" height="40" rx="8" fill="var(--vp-c-bg)" stroke="var(--vp-c-brand-1)"/><text :x="x(i)+80" :y="y(i)+25" text-anchor="middle" font-size="12">{{n}}</text></g></svg></template>
